import { TLayout, TResponsiveLayout, TBreakpoint, TBreakpoints } from '../../layout-definition';
import { cloneLayout } from '@/core/helpers/utils';
import { correctBounds } from '@/core/helpers/responsive-utils';
import { getCompactor } from '@/core/gridlayout/helpers/compactor';
import { ECompactType } from '@/core/gridlayout/enums/ECompactType';

/**
 * Given existing layouts and a new breakpoint, find or generate a new layout.
 *
 * This finds the layout above the new one and generates from it, if it exists.
 *
 * Despite a stale `// TODO obsolete code..` comment that used to sit on
 * this function's own parameter list (removed — see docs/REFACTORING.md
 * #54), this is not obsolete: it's the one function `useResponsiveLayout.ts`
 * calls on every breakpoint change, and has its own passing test suite
 * (`tests/responsive-helper.spec.ts`) exercising clone/bounds-correct/
 * compact behavior, immutability of the input, and the undefined-layout
 * edge case. Confirmed both directly before removing that comment,
 * rather than assuming it was safe to delete.
 *
 * @param  {TLayout}       orgLayout         Original layout.
 * @param  {TLayout}       layouts           Existing layouts.
 * @param  {TBreakpoints}  breakpoints       All breakpoints.
 * @param  {TBreakpoint}   breakpoint        New breakpoint.
 * @param  {TBreakpoint}   lastBreakpoint    Last breakpoint (for fallback).
 * @param  {Number}        cols              Column count at new breakpoint.
 * @param  {ECompactType}  compactType       Which built-in compaction strategy to apply.
 * @param  {Boolean}       distributeEvenly
 * @return {TLayout}                         New layout.
 */
export const findOrGenerateResponsiveLayout = (
  orgLayout: TLayout,
  layouts: TResponsiveLayout,
  breakpoints: TBreakpoints,
  breakpoint: TBreakpoint,
  lastBreakpoint: TBreakpoint,
  cols: number,
  compactType: ECompactType,
  distributeEvenly: boolean,
): TLayout => {
  // we cant return the layouts[breakpoints] directly because we don't know whether user change the layout or not

  // Find or generate the next layout
  const layout = cloneLayout(orgLayout || []);
  const bounded = correctBounds(layout, { cols }, distributeEvenly);

  return getCompactor(compactType).compact(bounded, cols, { compactType });
};

src/gridlayout/helpers/selection-range-h.source:
import { TLayout } from '../../layout-definition';

/**
 * Computes every item id in the contiguous range between `anchorId` and
 * `targetId`, inclusive of both — the standard Shift-click
 * range-selection gesture (file explorers, spreadsheets, most desktop
 * multi-select UIs). "Contiguous" here means by `layout`'s own array
 * order, not by screen position — the same proxy for "document order"
 * every framework package's own rendering already uses (`v-for`,
 * `.map()`, an Angular `@for`), so a Shift-click range visually spans
 * exactly the items rendered between the anchor and the target, in
 * every one of this project's three framework ports, without needing
 * three separate (and potentially inconsistent) "what does 'between'
 * mean" definitions.
 *
 * Deliberately order-independent from the caller's own perspective:
 * `anchorId` doesn't need to come before `targetId` in the layout
 * array — Shift-clicking "backwards" (toward an item earlier in the
 * layout than the anchor) is just as valid a range as clicking
 * forward, and produces the same set of ids either way (anchor and
 * target swapped has no effect on the result).
 *
 * @param layout The full layout array, in its own current order.
 * @param anchorId The range's own starting point — typically the last item selected without Shift (see each framework port's own `multiSelect` click-handling for how this is tracked).
 * @param targetId The item the range extends to — typically the one just Shift-clicked.
 * @return Every id from `anchorId` to `targetId` inclusive, in layout order. Falls back to `[targetId]` alone if either id doesn't match a real layout entry — a range with no valid anchor/target to span isn't a real range at all, and selecting just the clicked item is the least surprising fallback (matching what a plain, non-Shift click would have done).
 */
export function computeRangeSelection(
  layout: TLayout,
  anchorId: string | number,
  targetId: string | number,
): (string | number)[] {
  const anchorIndex = layout.findIndex(item => item.i === anchorId);
  const targetIndex = layout.findIndex(item => item.i === targetId);
  if(anchorIndex === -1 || targetIndex === -1) {
    return [targetId];
  }

  const startIndex = Math.min(anchorIndex, targetIndex);
  const endIndex = Math.max(anchorIndex, targetIndex);
  return layout.slice(startIndex, endIndex + 1).map(item => item.i);
}

src/gridlayout/helpers/sort-helper.ts.source:
import { ILayoutItem, TLayout } from '../../layout-definition';

/**
 * Get layout items sorted from top left to right and down — used before
 * compaction so items are processed in visual reading order, and each
 * item only collides with items already placed above/to-the-left of it.
 *
 * @param  {TLayout} layout   Array of layout objects.
 * @return {TLayout}          A new, sorted array (does not mutate `layout`).
 */
export function sortLayoutItemsByRowCol(layout: TLayout): TLayout {
  const a: ILayoutItem[] = [];
  return a.concat(layout).sort((itemA, itemB) => {
    if(itemA.y === itemB.y && itemA.x === itemB.x) {
      return 0;
    }

    if(itemA.y > itemB.y || (itemA.y === itemB.y && itemA.x > itemB.x)) {
      return 1;
    }

    return -1;
  });
}

/**
 * Get layout items sorted from top left to bottom and right — the
 * column-first counterpart to {@link sortLayoutItemsByRowCol} above,
 * used before *horizontal* compaction specifically. Processing items
 * leftmost-first (not topmost-first) means each item only collides
 * with items already placed to its left/above, mirroring
 * `sortLayoutItemsByRowCol`'s own row-major order but transposed —
 * the correct visual "reading order" for a layout that's settling
 * left-to-right instead of top-to-bottom.
 *
 * @param  {TLayout} layout   Array of layout objects.
 * @return {TLayout}          A new, sorted array (does not mutate `layout`).
 */
export function sortLayoutItemsByColRow(layout: TLayout): TLayout {
  const a: ILayoutItem[] = [];
  return a.concat(layout).sort((itemA, itemB) => {
    if(itemA.x === itemB.x && itemA.y === itemB.y) {
      return 0;
    }

    if(itemA.x > itemB.x || (itemA.x === itemB.x && itemA.y > itemB.y)) {
      return 1;
    }

    return -1;
  });
}

