      // pointerId:1's own gesture is still active — should be ignored,
      // not treated as ending the real gesture.
      el.dispatchEvent(new PointerEvent(`pointerup`, { bubbles: true, button: 0, clientX: 20, clientY: 20, pointerId: 2 }));
