import { describe, expect, it } from 'vitest';
import { findAlignmentGuides, findSnapAdjustment, findSpacingIndicators } from '../src/gridlayout/helpers/alignment-helper';

describe(`findSnapAdjustment`, () => {
  it(`Should snap x to align the active item's left edge with another item's left edge, within threshold`, () => {
    // other is wide enough that its right edge (x:20) is far outside
    // threshold, so only its left edge (x:0) is a candidate match.
    const layout = [
      { h: 2, i: `active`, w: 2, x: 3, y: 4 },
      { h: 2, i: `other`, w: 20, x: 0, y: 0 },
    ];

    const result = findSnapAdjustment(layout, layout[0], 3);

    expect(result.x).toBe(0);
  });

  it(`Should not snap when the nearest edge is further than threshold`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 5, y: 4 },
      { h: 2, i: `other`, w: 2, x: 0, y: 0 },
    ];

    const result = findSnapAdjustment(layout, layout[0], 2);

    expect(result.x).toBeUndefined();
  });

  it(`Should snap the active item's right edge to another item's left edge, adjusting for the item's own width`, () => {
    // active (w:2) right edge should land at other's left edge (x:6),
    // meaning active.x should snap to 6 - 2 = 4.
    const layout = [
      { h: 2, i: `active`, w: 2, x: 3, y: 4 },
      { h: 2, i: `other`, w: 2, x: 6, y: 0 },
    ];

    const result = findSnapAdjustment(layout, layout[0], 2);

    expect(result.x).toBe(4);
  });

  it(`Should snap y independently of x, on the vertical axis`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 8, y: 3 },
      { h: 20, i: `other`, w: 2, x: 0, y: 0 },
    ];

    const result = findSnapAdjustment(layout, layout[0], 3);

    expect(result.y).toBe(0);
    expect(result.x).toBeUndefined();
  });

  it(`Should pick the closest match when multiple items are within threshold`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 3, y: 4 },
      { h: 2, i: `far`, w: 2, x: 0, y: 0 },
      { h: 2, i: `near`, w: 2, x: 2, y: 10 },
    ];

    const result = findSnapAdjustment(layout, layout[0], 3);

    // "near" (distance 1) should win over "far" (distance 3).
    expect(result.x).toBe(2);
  });

  it(`Should never return a negative snapped position`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 1, y: 4 },
      { h: 2, i: `other`, w: 2, x: -3, y: 0 },
    ];

    const result = findSnapAdjustment(layout, layout[0], 3);

    expect(result.x).toBeGreaterThanOrEqual(0);
  });

  it(`Should return an empty object when threshold is 0`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 0, y: 4 },
      { h: 2, i: `other`, w: 2, x: 0, y: 0 },
    ];

    const result = findSnapAdjustment(layout, layout[0], 0);

    expect(result).toStrictEqual({});
  });

  it(`Should snap when the distance is exactly equal to threshold, not just strictly less than it`, () => {
    // Every other test above uses a distance clearly inside threshold
    // (never exactly at the edge), so "distance <= threshold" and a
    // mutated "distance < threshold" were never actually distinguished.
    // other is wide enough (w:100) that every OTHER edge-combo
    // (left-to-right, right-to-left, right-to-right) is far outside
    // threshold, isolating left-to-left as the only qualifying combo.
    const layout = [
      { h: 2, i: `active`, w: 2, x: 10, y: 4 },
      { h: 2, i: `other`, w: 100, x: 7, y: 0 }, // left edge at x=7, distance exactly 3
    ];

    const result = findSnapAdjustment(layout, layout[0], 3);

    expect(result.x).toBe(7);
  });

  it(`Should keep the FIRST match found when two candidates are exactly equidistant, not the later one`, () => {
    // "distance < bestXDistance" is a strict less-than — a later
    // candidate at the exact same distance as the current best should
    // NOT replace it. Every existing "closest match" test above uses
    // clearly different distances, never a genuine tie, so a mutated
    // "<=" was never distinguished from the real "<".
    //
    // "first"'s own closest edge-combo (activeLeft(5) vs its right
    // edge(4)) is distance 1, setting bestX=4. "second"'s own closest
    // combo (activeRight(7) vs its left edge(8)) is ALSO distance 1,
    // encountered later — the genuine tie this test targets.
    const layout = [
      { h: 2, i: `active`, w: 2, x: 5, y: 4 },
      { h: 2, i: `first`, w: 2, x: 2, y: 0 },
      { h: 2, i: `second`, w: 2, x: 8, y: 0 },
    ];

    const result = findSnapAdjustment(layout, layout[0], 3);

    // If "second" incorrectly won the tie, x would resolve via its own
    // left edge (8), adjusted for active's width (8 - 2 = 6), instead
    // of "first"'s own right edge (4).
    expect(result.x).toBe(4);
  });

  it(`Should return an empty object when nothing else is in the layout`, () => {
    const layout = [{ h: 2, i: `active`, w: 2, x: 5, y: 5 }];

    const result = findSnapAdjustment(layout, layout[0], 3);

    expect(result).toStrictEqual({});
  });

  it(`Should snap the active item's left edge to another item's right edge (the remaining untested x edge-combination)`, () => {
    // active's left edge (x:6) near other's right edge (x:0+5=5).
    const layout = [
      { h: 2, i: `active`, w: 2, x: 6, y: 4 },
      { h: 2, i: `other`, w: 5, x: 0, y: 0 },
    ];

    const result = findSnapAdjustment(layout, layout[0], 2);

    expect(result.x).toBe(5);
  });

  it(`Should snap the active item's right edge to another item's right edge (the remaining untested x edge-combination)`, () => {
    // Isolated so only right-to-right falls within threshold: active's
    // left edge (10) is far from other's left (0) and right (14) edges;
    // only active's right edge (12) is close to other's right (14).
    const layout = [
      { h: 2, i: `active`, w: 2, x: 10, y: 4 },
      { h: 2, i: `other`, w: 14, x: 0, y: 0 },
    ];

    const result = findSnapAdjustment(layout, layout[0], 3);

    expect(result.x).toBe(12);
  });

  it(`Should snap on the remaining three untested y edge-combinations (top-to-bottom, bottom-to-top, bottom-to-bottom)`, () => {
    // top-to-bottom: active's top edge (y:6) near other's bottom edge (y:0+5=5).
    const topToBottom = [
      { h: 2, i: `active`, w: 2, x: 4, y: 6 },
      { h: 5, i: `other`, w: 2, x: 0, y: 0 },
    ];
    expect(findSnapAdjustment(topToBottom, topToBottom[0], 2).y).toBe(5);

    // bottom-to-top: active's bottom edge (y:0+2=2) near other's top edge (y:5).
    const bottomToTop = [
      { h: 2, i: `active`, w: 2, x: 4, y: 0 },
      { h: 3, i: `other`, w: 2, x: 0, y: 5 },
    ];
    expect(findSnapAdjustment(bottomToTop, bottomToTop[0], 3).y).toBe(3);

    // bottom-to-bottom: isolated so only this combo falls within
    // threshold — active's top edge (10) is far from other's top (0)
    // and bottom (14) edges; only active's bottom edge (12) is close
    // to other's bottom (14).
    const bottomToBottom = [
      { h: 2, i: `active`, w: 2, x: 4, y: 10 },
      { h: 14, i: `other`, w: 2, x: 0, y: 0 },
    ];
    expect(findSnapAdjustment(bottomToBottom, bottomToBottom[0], 3).y).toBe(12);
  });
});


describe(`findAlignmentGuides`, () => {
  it(`Should find a vertical guide when the active item's left edge matches another item's left edge`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 0, y: 4 },
      { h: 2, i: `other`, w: 2, x: 0, y: 0 },
    ];

    const guides = findAlignmentGuides(layout, layout[0]);

    expect(guides).toContainEqual({ axis: `x`, position: 0 });
  });

  it(`Should find a vertical guide when the active item's left edge matches another item's right edge`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 4, y: 0 },
      { h: 2, i: `other`, w: 2, x: 2, y: 4 }, // right edge at x=4
    ];

    const guides = findAlignmentGuides(layout, layout[0]);

    expect(guides).toContainEqual({ axis: `x`, position: 4 });
  });

  it(`Should find a vertical guide when the active item's right edge matches another item's right edge`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 2, y: 0 }, // right edge at x=4
      { h: 2, i: `other`, w: 4, x: 0, y: 4 }, // right edge at x=4
    ];

    const guides = findAlignmentGuides(layout, layout[0]);

    expect(guides).toContainEqual({ axis: `x`, position: 4 });
  });

  it(`Should find a horizontal guide when the active item's top edge matches another item's top edge`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 4, y: 0 },
      { h: 2, i: `other`, w: 2, x: 0, y: 0 },
    ];

    const guides = findAlignmentGuides(layout, layout[0]);

    expect(guides).toContainEqual({ axis: `y`, position: 0 });
  });

  it(`Should find a horizontal guide when the active item's bottom edge matches another item's bottom edge`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 4, y: 2 }, // bottom edge at y=4
      { h: 4, i: `other`, w: 2, x: 0, y: 0 }, // bottom edge at y=4
    ];

    const guides = findAlignmentGuides(layout, layout[0]);

    expect(guides).toContainEqual({ axis: `y`, position: 4 });
  });

  it(`Should find both a vertical and horizontal guide when both align`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 0, y: 0 },
      { h: 2, i: `other`, w: 2, x: 0, y: 4 }, // same left edge (x=0), different row
    ];

    const guides = findAlignmentGuides(layout, layout[0]);

    expect(guides).toContainEqual({ axis: `x`, position: 0 });
  });

  it(`Should return no guides when nothing aligns`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 1, y: 1 },
      { h: 2, i: `other`, w: 2, x: 5, y: 5 },
    ];

    expect(findAlignmentGuides(layout, layout[0])).toStrictEqual([]);
  });

  it(`Should exclude the active item itself from comparison`, () => {
    // Without the i !== activeItem.i filter, the active item would
    // trivially "align" with itself on every edge.
    const layout = [{ h: 2, i: `active`, w: 2, x: 0, y: 0 }];

    expect(findAlignmentGuides(layout, layout[0])).toStrictEqual([]);
  });

  it(`Should deduplicate when multiple other items share the same aligned edge`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 0, y: 0 },
      { h: 2, i: `other1`, w: 2, x: 0, y: 4 },
      { h: 2, i: `other2`, w: 4, x: 0, y: 8 },
    ];

    const guides = findAlignmentGuides(layout, layout[0]).filter((g) => g.axis === `x` && g.position === 0);

    expect(guides).toHaveLength(1);
  });

  it(`Should return no guides for an empty layout (only the active item, already excluded)`, () => {
    expect(findAlignmentGuides([], { h: 2, i: `active`, w: 2, x: 0, y: 0 })).toStrictEqual([]);
  });
});

describe(`findSpacingIndicators`, () => {
  it(`Should find the gap to a neighbor on the left`, () => {
    const layout = [
      { h: 2, i: `other`, w: 2, x: 0, y: 0 },
      { h: 2, i: `active`, w: 2, x: 5, y: 0 },
    ];

    const indicators = findSpacingIndicators(layout, layout[1]);

    expect(indicators).toContainEqual({ axis: `x`, distance: 3, gapEnd: 5, gapStart: 2 });
  });

  it(`Should find the gap to a neighbor on the right`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 0, y: 0 },
      { h: 2, i: `other`, w: 2, x: 5, y: 0 },
    ];

    const indicators = findSpacingIndicators(layout, layout[0]);

    expect(indicators).toContainEqual({ axis: `x`, distance: 3, gapEnd: 5, gapStart: 2 });
  });

  it(`Should find the gap to a neighbor above`, () => {
    const layout = [
      { h: 2, i: `other`, w: 2, x: 0, y: 0 },
      { h: 2, i: `active`, w: 2, x: 0, y: 6 },
    ];

    const indicators = findSpacingIndicators(layout, layout[1]);

    expect(indicators).toContainEqual({ axis: `y`, distance: 4, gapEnd: 6, gapStart: 2 });
  });

  it(`Should find the gap to a neighbor below`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 0, y: 0 },
      { h: 2, i: `other`, w: 2, x: 0, y: 6 },
    ];

    const indicators = findSpacingIndicators(layout, layout[0]);

    expect(indicators).toContainEqual({ axis: `y`, distance: 4, gapEnd: 6, gapStart: 2 });
  });

  it(`Should find all four sides' gaps at once when neighbors exist on every side`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 5, y: 5 },
      { h: 2, i: `left`, w: 2, x: 0, y: 5 },
      { h: 2, i: `right`, w: 2, x: 8, y: 5 },
      { h: 2, i: `top`, w: 2, x: 5, y: 0 },
      { h: 2, i: `bottom`, w: 2, x: 5, y: 8 },
    ];

    const indicators = findSpacingIndicators(layout, layout[0]);

    expect(indicators).toHaveLength(4);
  });

  it(`Should pick the nearest neighbor per side, not every item on that side`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 10, y: 0 },
      { h: 2, i: `far`, w: 2, x: 0, y: 0 },
      { h: 2, i: `near`, w: 2, x: 6, y: 0 },
    ];

    const indicators = findSpacingIndicators(layout, layout[0]);
    const leftGap = indicators.find(indicator => indicator.axis === `x` && indicator.gapEnd === 10);

    // "near"'s right edge (8) should win over "far"'s (2).
    expect(leftGap?.gapStart).toBe(8);
    expect(leftGap?.distance).toBe(2);
  });

  it(`Should pick the nearest of multiple candidates on the right side too, not just the left`, () => {
    // The test above only ever exercises the left-side "pick the
    // nearer candidate" comparison (otherRight > bestLeft) — this is a
    // separate branch (otherLeft < bestRight) that needs its own
    // multi-candidate case to exercise.
    const layout = [
      { h: 2, i: `active`, w: 2, x: 0, y: 0 },
      { h: 2, i: `far`, w: 2, x: 20, y: 0 },
      { h: 2, i: `near`, w: 2, x: 6, y: 0 },
    ];

    const indicators = findSpacingIndicators(layout, layout[0]);
    const rightGap = indicators.find(indicator => indicator.axis === `x` && indicator.gapStart === 2);

    // "near"'s left edge (6) should win over "far"'s (20).
    expect(rightGap?.gapEnd).toBe(6);
    expect(rightGap?.distance).toBe(4);
  });

  it(`Should pick the nearest of multiple candidates above, too`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 0, y: 10 },
      { h: 2, i: `far`, w: 2, x: 0, y: 0 },
      { h: 2, i: `near`, w: 2, x: 0, y: 6 },
    ];

    const indicators = findSpacingIndicators(layout, layout[0]);
    const topGap = indicators.find(indicator => indicator.axis === `y` && indicator.gapEnd === 10);

    // "near"'s bottom edge (8) should win over "far"'s (2).
    expect(topGap?.gapStart).toBe(8);
    expect(topGap?.distance).toBe(2);
  });

  it(`Should pick the nearest of multiple candidates below, too`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 0, y: 0 },
      { h: 2, i: `far`, w: 2, x: 0, y: 20 },
      { h: 2, i: `near`, w: 2, x: 0, y: 6 },
    ];

    const indicators = findSpacingIndicators(layout, layout[0]);
    const bottomGap = indicators.find(indicator => indicator.axis === `y` && indicator.gapStart === 2);

    // "near"'s top edge (6) should win over "far"'s (20).
    expect(bottomGap?.gapEnd).toBe(6);
    expect(bottomGap?.distance).toBe(4);
  });

  it(`Should ignore a candidate whose perpendicular range doesn't overlap activeItem's, even though it's on the same side`, () => {
    // "other" sits to the left in x, but its y-range (10-12) doesn't
    // overlap active's (0-2) at all — not a real left neighbor.
    const layout = [
      { h: 2, i: `active`, w: 2, x: 5, y: 0 },
      { h: 2, i: `other`, w: 2, x: 0, y: 10 },
    ];

    expect(findSpacingIndicators(layout, layout[0])).toStrictEqual([]);
  });

  // The yOverlaps/xOverlaps check in each of the four "nearest neighbor"
  // loops is `otherTop < activeBottom && otherBottom > activeTop` (or the
  // x-axis equivalent) — the test above has BOTH halves false at once
  // (other's y-range is entirely below active's), which can't
  // distinguish either half's own mutants from the other. Each pair
  // below isolates one half as the sole reason the candidate is ignored,
  // with the other half genuinely true.
  it(`Should ignore a left-side candidate when only otherTop < activeBottom is false (otherBottom > activeTop is still true)`, () => {
    // other's y-range (5-7) starts at/after active's bottom (0-2), so
    // otherTop(5) < activeBottom(2) is false — but otherBottom(7) >
    // activeTop(0) is true, isolating the first half specifically.
    const layout = [
      { h: 2, i: `active`, w: 2, x: 5, y: 0 },
      { h: 2, i: `other`, w: 2, x: 0, y: 5 },
    ];

    expect(findSpacingIndicators(layout, layout[0])).toStrictEqual([]);
  });

  it(`Should ignore a left-side candidate when only otherBottom > activeTop is false (otherTop < activeBottom is still true)`, () => {
    // other's y-range (-5 to -3) ends at/before active's top (5-7), so
    // otherBottom(-3) > activeTop(5) is false — but otherTop(-5) <
    // activeBottom(7) is true, isolating the second half specifically.
    const layout = [
      { h: 2, i: `active`, w: 2, x: 5, y: 5 },
      { h: 2, i: `other`, w: 2, x: 0, y: -5 },
    ];

    expect(findSpacingIndicators(layout, layout[0])).toStrictEqual([]);
  });

  it(`Should ignore a right-side candidate when only otherTop < activeBottom is false`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 0, y: 0 },
      { h: 2, i: `other`, w: 2, x: 5, y: 5 },
    ];

    expect(findSpacingIndicators(layout, layout[0])).toStrictEqual([]);
  });

  it(`Should ignore a right-side candidate when only otherBottom > activeTop is false`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 0, y: 5 },
      { h: 2, i: `other`, w: 2, x: 5, y: -5 },
    ];

    expect(findSpacingIndicators(layout, layout[0])).toStrictEqual([]);
  });

  it(`Should ignore a top-side candidate when only otherLeft < activeRight is false`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 0, y: 5 },
      { h: 2, i: `other`, w: 2, x: 5, y: 0 },
    ];

    expect(findSpacingIndicators(layout, layout[0])).toStrictEqual([]);
  });

  it(`Should ignore a top-side candidate when only otherRight > activeLeft is false`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 5, y: 5 },
      { h: 2, i: `other`, w: 2, x: -5, y: 0 },
    ];

    expect(findSpacingIndicators(layout, layout[0])).toStrictEqual([]);
  });

  it(`Should ignore a bottom-side candidate when only otherLeft < activeRight is false`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 0, y: 0 },
      { h: 2, i: `other`, w: 2, x: 5, y: 5 },
    ];

    expect(findSpacingIndicators(layout, layout[0])).toStrictEqual([]);
  });

  it(`Should ignore a bottom-side candidate when only otherRight > activeLeft is false`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 5, y: 0 },
      { h: 2, i: `other`, w: 2, x: -5, y: 5 },
    ];

    expect(findSpacingIndicators(layout, layout[0])).toStrictEqual([]);
  });

  // The isolation tests above use values clearly on one side or the
  // other of the yOverlaps/xOverlaps boundary — that distinguishes
  // LogicalOperator (&&/||) mutants, but NOT EqualityOperator ones
  // (< vs <=, > vs >=), since those only diverge when a value sits
  // EXACTLY at the boundary (touching, not overlapping). Each test
  // below uses an other item whose relevant edge exactly equals
  // activeItem's, which correctly-implemented "strictly less/greater
  // than" treats as NOT overlapping (touching isn't overlapping).
  it(`Should treat a left-side candidate exactly touching (otherTop === activeBottom) as NOT overlapping`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 5, y: 0 }, // bottom edge at y=2
      { h: 2, i: `other`, w: 2, x: 0, y: 2 }, // top edge at y=2, exactly touching
    ];

    expect(findSpacingIndicators(layout, layout[0])).toStrictEqual([]);
  });

  it(`Should treat a left-side candidate exactly touching (otherBottom === activeTop) as NOT overlapping`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 5, y: 5 }, // top edge at y=5
      { h: 2, i: `other`, w: 2, x: 0, y: 3 }, // bottom edge at y=5, exactly touching
    ];

    expect(findSpacingIndicators(layout, layout[0])).toStrictEqual([]);
  });

  it(`Should treat a top-side candidate exactly touching (otherLeft === activeRight) as NOT overlapping`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 0, y: 5 }, // right edge at x=2
      { h: 2, i: `other`, w: 2, x: 2, y: 0 }, // left edge at x=2, exactly touching
    ];

    expect(findSpacingIndicators(layout, layout[0])).toStrictEqual([]);
  });

  it(`Should treat a top-side candidate exactly touching (otherRight === activeLeft) as NOT overlapping`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 5, y: 5 }, // left edge at x=5
      { h: 2, i: `other`, w: 2, x: 3, y: 0 }, // right edge at x=5, exactly touching
    ];

    expect(findSpacingIndicators(layout, layout[0])).toStrictEqual([]);
  });

  it(`Should not report a gap for items already touching (distance 0)`, () => {
    const layout = [
      { h: 2, i: `active`, w: 2, x: 2, y: 0 },
      { h: 2, i: `other`, w: 2, x: 0, y: 0 },
    ];

    expect(findSpacingIndicators(layout, layout[0])).toStrictEqual([]);
  });

  it(`Should return no indicators when nothing else is in the layout`, () => {
    expect(findSpacingIndicators([], { h: 2, i: `active`, w: 2, x: 5, y: 5 })).toStrictEqual([]);
  });

  it(`Should exclude the active item itself from comparison`, () => {
    const layout = [{ h: 2, i: `active`, w: 2, x: 0, y: 0 }];

    expect(findSpacingIndicators(layout, layout[0])).toStrictEqual([]);
  });
});

